#include <iostream>
using namespace std;

const int MAXN = 1000005;
bool composite[MAXN];

int main() {
    int n;
    if (!(cin >> n)) return 0;

    int count = 0;
    for (int i = 2; i <= n; i++) {
        if (!composite[i]) {
            count++;
            if ((long long)i * i <= n) {
                for (long long j = (long long)i * i; j <= n; j += i) {
                    composite[j] = true;
                }
            }
        }
    }
    cout << count << "\n";
    return 0;
}
